// Tracked: EF Core allocates and monitors each Product entity
var trackedProducts = await dbContext.Products
    .Where(p => p.Category.Name == "Electronics")
    .ToListAsync();

trackedProducts[0].Price = 99.99m;
await dbContext.SaveChangesAsync(); // Produces an UPDATE

// No tracking: faster, lighter, but changes are ignored
var readOnlyProducts = await dbContext.Products
    .AsNoTracking()
    .Where(p => p.Category.Name == "Electronics")
    .ToListAsync();

readOnlyProducts[0].Price = 99.99m;
await dbContext.SaveChangesAsync(); // No UPDATE — entity was never tracked

var summaries = await dbContext.Orders
    .AsNoTracking()
    .Where(o => o.OrderDate >= DateTime.UtcNow.AddMonths(-1))
    .Select(o => new OrderSummaryDto
    {
        Id = o.Id,
        CustomerName = o.Customer.FullName,
        Total = o.OrderItems.Sum(oi => oi.Quantity * oi.UnitPrice)
    })
    .ToListAsync();
